insert into public.reconciliations (id, user_id, prescription_medicines, dispensed_medicines, matched, missing, unexpected, is_exact_match, notes, created_at, updated_at, data) values
  ('demo-patient-ramesh-kumar-reconciliation-1', 'demo-patient-ramesh-kumar', '["Metformin 500 mg","Telmisartan 40 mg","Atorvastatin 10 mg","Glimepiride 1 mg"]'::jsonb, '["Metformin 500 mg","Telmisartan 40 mg","Atorvastatin 10 mg","Paracetamol 500 mg"]'::jsonb, '[{"name":"Metformin 500 mg","count":1},{"name":"Telmisartan 40 mg","count":1},{"name":"Atorvastatin 10 mg","count":1}]'::jsonb, '[{"name":"Glimepiride 1 mg","count":1}]'::jsonb, '[{"name":"Paracetamol 500 mg","count":1}]'::jsonb, false, 'Glimepiride 1 mg was out of stock at the pharmacy on the collection date. Paracetamol 500 mg was bought over the counter for knee pain — confirm it is safe alongside the current regimen.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-ramesh-kumar-reconciliation-1","userId":"demo-patient-ramesh-kumar","prescriptionMedicines":["Metformin 500 mg","Telmisartan 40 mg","Atorvastatin 10 mg","Glimepiride 1 mg"],"dispensedMedicines":["Metformin 500 mg","Telmisartan 40 mg","Atorvastatin 10 mg","Paracetamol 500 mg"],"matched":[{"name":"Metformin 500 mg","count":1},{"name":"Telmisartan 40 mg","count":1},{"name":"Atorvastatin 10 mg","count":1}],"missing":[{"name":"Glimepiride 1 mg","count":1}],"unexpected":[{"name":"Paracetamol 500 mg","count":1}],"isExactMatch":false,"notes":"Glimepiride 1 mg was out of stock at the pharmacy on the collection date. Paracetamol 500 mg was bought over the counter for knee pain — confirm it is safe alongside the current regimen.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-sunita-devi-reconciliation-1', 'demo-patient-sunita-devi', '["Levothyroxine 50 mcg","Ferrous Sulphate 200 mg","Calcium Carbonate 500 mg"]'::jsonb, '["Thyronorm 50 mcg","Ferrous Sulphate 200 mg","Calcium Carbonate 500 mg"]'::jsonb, '[{"name":"Ferrous Sulphate 200 mg","count":1},{"name":"Calcium Carbonate 500 mg","count":1}]'::jsonb, '[{"name":"Levothyroxine 50 mcg","count":1}]'::jsonb, '[{"name":"Thyronorm 50 mcg","count":1}]'::jsonb, false, 'The pharmacy dispensed the brand formulation (Thyronorm) of the same 50 mcg levothyroxine tablet. Confirm the strength and the empty-stomach timing before the next dose.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-sunita-devi-reconciliation-1","userId":"demo-patient-sunita-devi","prescriptionMedicines":["Levothyroxine 50 mcg","Ferrous Sulphate 200 mg","Calcium Carbonate 500 mg"],"dispensedMedicines":["Thyronorm 50 mcg","Ferrous Sulphate 200 mg","Calcium Carbonate 500 mg"],"matched":[{"name":"Ferrous Sulphate 200 mg","count":1},{"name":"Calcium Carbonate 500 mg","count":1}],"missing":[{"name":"Levothyroxine 50 mcg","count":1}],"unexpected":[{"name":"Thyronorm 50 mcg","count":1}],"isExactMatch":false,"notes":"The pharmacy dispensed the brand formulation (Thyronorm) of the same 50 mcg levothyroxine tablet. Confirm the strength and the empty-stomach timing before the next dose.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-joseph-thomas-reconciliation-1', 'demo-patient-joseph-thomas', '["Aspirin 75 mg","Clopidogrel 75 mg","Atorvastatin 40 mg","Metoprolol 50 mg","Ramipril 5 mg"]'::jsonb, '["Aspirin 75 mg","Atorvastatin 40 mg","Metoprolol 50 mg","Ramipril 5 mg","Ibuprofen 400 mg"]'::jsonb, '[{"name":"Aspirin 75 mg","count":1},{"name":"Atorvastatin 40 mg","count":1},{"name":"Metoprolol 50 mg","count":1},{"name":"Ramipril 5 mg","count":1}]'::jsonb, '[{"name":"Clopidogrel 75 mg","count":1}]'::jsonb, '[{"name":"Ibuprofen 400 mg","count":1}]'::jsonb, false, 'Clopidogrel 75 mg was not dispensed because the pharmacist asked for a fresh prescription copy for a schedule medicine. Ibuprofen 400 mg was self-purchased for knee pain.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-joseph-thomas-reconciliation-1","userId":"demo-patient-joseph-thomas","prescriptionMedicines":["Aspirin 75 mg","Clopidogrel 75 mg","Atorvastatin 40 mg","Metoprolol 50 mg","Ramipril 5 mg"],"dispensedMedicines":["Aspirin 75 mg","Atorvastatin 40 mg","Metoprolol 50 mg","Ramipril 5 mg","Ibuprofen 400 mg"],"matched":[{"name":"Aspirin 75 mg","count":1},{"name":"Atorvastatin 40 mg","count":1},{"name":"Metoprolol 50 mg","count":1},{"name":"Ramipril 5 mg","count":1}],"missing":[{"name":"Clopidogrel 75 mg","count":1}],"unexpected":[{"name":"Ibuprofen 400 mg","count":1}],"isExactMatch":false,"notes":"Clopidogrel 75 mg was not dispensed because the pharmacist asked for a fresh prescription copy for a schedule medicine. Ibuprofen 400 mg was self-purchased for knee pain.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-priya-menon-reconciliation-1', 'demo-patient-priya-menon', '["Ferrous Sulphate 200 mg","Folic Acid 5 mg","Vitamin D3 60,000 IU","Pantoprazole 40 mg"]'::jsonb, '["Ferrous Sulphate 200 mg","Folic Acid 5 mg","Vitamin D3 60,000 IU","Pantoprazole 40 mg"]'::jsonb, '[{"name":"Ferrous Sulphate 200 mg","count":1},{"name":"Folic Acid 5 mg","count":1},{"name":"Vitamin D3 60","count":1},{"name":"000 IU","count":1},{"name":"Pantoprazole 40 mg","count":1}]'::jsonb, '[]'::jsonb, '[]'::jsonb, true, 'All four medicines were dispensed exactly as prescribed. Keep the weekly vitamin D sachet on the same day each week.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-priya-menon-reconciliation-1","userId":"demo-patient-priya-menon","prescriptionMedicines":["Ferrous Sulphate 200 mg","Folic Acid 5 mg","Vitamin D3 60,000 IU","Pantoprazole 40 mg"],"dispensedMedicines":["Ferrous Sulphate 200 mg","Folic Acid 5 mg","Vitamin D3 60,000 IU","Pantoprazole 40 mg"],"matched":[{"name":"Ferrous Sulphate 200 mg","count":1},{"name":"Folic Acid 5 mg","count":1},{"name":"Vitamin D3 60","count":1},{"name":"000 IU","count":1},{"name":"Pantoprazole 40 mg","count":1}],"missing":[],"unexpected":[],"isExactMatch":true,"notes":"All four medicines were dispensed exactly as prescribed. Keep the weekly vitamin D sachet on the same day each week.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-lakshmi-devi-reconciliation-1', 'demo-patient-lakshmi-devi', '["Tiotropium 18 mcg","Salbutamol 100 mcg","Prednisolone 5 mg","Amoxicillin 500 mg"]'::jsonb, '["Tiotropium 18 mcg","Salbutamol 100 mcg","Prednisolone 5 mg","Amoxicillin 500 mg"]'::jsonb, '[{"name":"Tiotropium 18 mcg","count":1},{"name":"Salbutamol 100 mcg","count":1},{"name":"Prednisolone 5 mg","count":1},{"name":"Amoxicillin 500 mg","count":1}]'::jsonb, '[]'::jsonb, '[]'::jsonb, true, 'Every medicine on the prescription was dispensed, including the antibiotic course. The name comparison alone does not confirm whether the antibiotic is safe for you — the allergy on your record needs a clinician check.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-lakshmi-devi-reconciliation-1","userId":"demo-patient-lakshmi-devi","prescriptionMedicines":["Tiotropium 18 mcg","Salbutamol 100 mcg","Prednisolone 5 mg","Amoxicillin 500 mg"],"dispensedMedicines":["Tiotropium 18 mcg","Salbutamol 100 mcg","Prednisolone 5 mg","Amoxicillin 500 mg"],"matched":[{"name":"Tiotropium 18 mcg","count":1},{"name":"Salbutamol 100 mcg","count":1},{"name":"Prednisolone 5 mg","count":1},{"name":"Amoxicillin 500 mg","count":1}],"missing":[],"unexpected":[],"isExactMatch":true,"notes":"Every medicine on the prescription was dispensed, including the antibiotic course. The name comparison alone does not confirm whether the antibiotic is safe for you — the allergy on your record needs a clinician check.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-fatima-khan-reconciliation-1', 'demo-patient-fatima-khan', '["Methotrexate 10 mg","Folic Acid 5 mg","Hydroxychloroquine 200 mg","Prednisolone 5 mg"]'::jsonb, '["Methotrexate 10 mg","Folic Acid 5 mg","Hydroxychloroquine 200 mg","Prednisolone 5 mg","Naproxen 500 mg"]'::jsonb, '[{"name":"Methotrexate 10 mg","count":1},{"name":"Folic Acid 5 mg","count":1},{"name":"Hydroxychloroquine 200 mg","count":1},{"name":"Prednisolone 5 mg","count":1}]'::jsonb, '[]'::jsonb, '[{"name":"Naproxen 500 mg","count":1}]'::jsonb, false, 'Naproxen 500 mg was added from the counter for joint pain. The methotrexate label on the pack reads “once daily” — methotrexate is taken once a week, so please confirm the schedule with the pharmacist.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-fatima-khan-reconciliation-1","userId":"demo-patient-fatima-khan","prescriptionMedicines":["Methotrexate 10 mg","Folic Acid 5 mg","Hydroxychloroquine 200 mg","Prednisolone 5 mg"],"dispensedMedicines":["Methotrexate 10 mg","Folic Acid 5 mg","Hydroxychloroquine 200 mg","Prednisolone 5 mg","Naproxen 500 mg"],"matched":[{"name":"Methotrexate 10 mg","count":1},{"name":"Folic Acid 5 mg","count":1},{"name":"Hydroxychloroquine 200 mg","count":1},{"name":"Prednisolone 5 mg","count":1}],"missing":[],"unexpected":[{"name":"Naproxen 500 mg","count":1}],"isExactMatch":false,"notes":"Naproxen 500 mg was added from the counter for joint pain. The methotrexate label on the pack reads “once daily” — methotrexate is taken once a week, so please confirm the schedule with the pharmacist.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-ravi-shankar-reconciliation-1', 'demo-patient-ravi-shankar', '["Omeprazole 20 mg","Domperidone 10 mg","Atorvastatin 10 mg"]'::jsonb, '["Omeprazole 20 mg","Domperidone 10 mg","Atorvastatin 10 mg","Pantoprazole 40 mg"]'::jsonb, '[{"name":"Omeprazole 20 mg","count":1},{"name":"Domperidone 10 mg","count":1},{"name":"Atorvastatin 10 mg","count":1}]'::jsonb, '[]'::jsonb, '[{"name":"Pantoprazole 40 mg","count":1}]'::jsonb, false, 'Pantoprazole 40 mg is left over from the previous prescription and is still being taken. Two proton-pump inhibitors at the same time should be reviewed.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-ravi-shankar-reconciliation-1","userId":"demo-patient-ravi-shankar","prescriptionMedicines":["Omeprazole 20 mg","Domperidone 10 mg","Atorvastatin 10 mg"],"dispensedMedicines":["Omeprazole 20 mg","Domperidone 10 mg","Atorvastatin 10 mg","Pantoprazole 40 mg"],"matched":[{"name":"Omeprazole 20 mg","count":1},{"name":"Domperidone 10 mg","count":1},{"name":"Atorvastatin 10 mg","count":1}],"missing":[],"unexpected":[{"name":"Pantoprazole 40 mg","count":1}],"isExactMatch":false,"notes":"Pantoprazole 40 mg is left over from the previous prescription and is still being taken. Two proton-pump inhibitors at the same time should be reviewed.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb),
  ('demo-patient-anjali-sharma-reconciliation-1', 'demo-patient-anjali-sharma', '["Sertraline 50 mg","Lorazepam 10 mg","Ibuprofen 400 mg"]'::jsonb, '["Sertraline 50 mg","Lorazepam 10 mg","Ibuprofen 400 mg","Paracetamol 500 mg","Melatonin 3 mg"]'::jsonb, '[{"name":"Sertraline 50 mg","count":1},{"name":"Lorazepam 10 mg","count":1},{"name":"Ibuprofen 400 mg","count":1}]'::jsonb, '[]'::jsonb, '[{"name":"Paracetamol 500 mg","count":1},{"name":"Melatonin 3 mg","count":1}]'::jsonb, false, 'Paracetamol 500 mg and a 3 mg melatonin sleep aid were added at the pharmacy counter. Ibuprofen is recorded as causing stomach irritation, so please confirm the best pain relief for migraine with the prescriber.', '2026-10-17T09:00:00.000Z', '2026-10-17T09:00:00.000Z', '{"id":"demo-patient-anjali-sharma-reconciliation-1","userId":"demo-patient-anjali-sharma","prescriptionMedicines":["Sertraline 50 mg","Lorazepam 10 mg","Ibuprofen 400 mg"],"dispensedMedicines":["Sertraline 50 mg","Lorazepam 10 mg","Ibuprofen 400 mg","Paracetamol 500 mg","Melatonin 3 mg"],"matched":[{"name":"Sertraline 50 mg","count":1},{"name":"Lorazepam 10 mg","count":1},{"name":"Ibuprofen 400 mg","count":1}],"missing":[],"unexpected":[{"name":"Paracetamol 500 mg","count":1},{"name":"Melatonin 3 mg","count":1}],"isExactMatch":false,"notes":"Paracetamol 500 mg and a 3 mg melatonin sleep aid were added at the pharmacy counter. Ibuprofen is recorded as causing stomach irritation, so please confirm the best pain relief for migraine with the prescriber.","createdAt":"2026-10-17T09:00:00.000Z"}'::jsonb)
