insert into public.indications (id, doctor_user_id, patient_user_id, title, detail, severity, created_at, updated_at, data) values
  ('demo-patient-ramesh-kumar-indication-1', 'demo-doctor-ananya-rao', 'demo-patient-ramesh-kumar', 'Start Glimepiride only after the pharmacy confirms supply', 'The comparison shows Glimepiride 1 mg was prescribed but not dispensed. Please start it from the first collection where it is in stock, and note the start date.', 'review', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-ramesh-kumar-indication-1","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-ramesh-kumar","title":"Start Glimepiride only after the pharmacy confirms supply","detail":"The comparison shows Glimepiride 1 mg was prescribed but not dispensed. Please start it from the first collection where it is in stock, and note the start date.","severity":"review","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-ramesh-kumar-indication-2', 'demo-doctor-ananya-rao', 'demo-patient-ramesh-kumar', 'Paracetamol bought over the counter', 'Paracetamol 500 mg is not part of this plan. Keep taking it for knee pain only after a pharmacist confirms it fits with your diabetes and blood pressure treatment.', 'info', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-ramesh-kumar-indication-2","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-ramesh-kumar","title":"Paracetamol bought over the counter","detail":"Paracetamol 500 mg is not part of this plan. Keep taking it for knee pain only after a pharmacist confirms it fits with your diabetes and blood pressure treatment.","severity":"info","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb),
  ('demo-patient-sunita-devi-indication-1', 'demo-doctor-meera-iyer', 'demo-patient-sunita-devi', 'Repeat TSH before any dose change', 'The last thyroid panel was seven months ago. Repeat TSH and free T4 before the levothyroxine dose is adjusted at the next visit.', 'review', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-sunita-devi-indication-1","doctorUserId":"demo-doctor-meera-iyer","patientUserId":"demo-patient-sunita-devi","title":"Repeat TSH before any dose change","detail":"The last thyroid panel was seven months ago. Repeat TSH and free T4 before the levothyroxine dose is adjusted at the next visit.","severity":"review","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-sunita-devi-indication-2', 'demo-doctor-meera-iyer', 'demo-patient-sunita-devi', 'Brand versus generic levothyroxine', 'Your record shows levothyroxine 50 mcg, and the pharmacy dispensed Thyronorm 50 mcg. Please confirm both are the 50 mcg strength and take them the same way.', 'info', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-sunita-devi-indication-2","doctorUserId":"demo-doctor-meera-iyer","patientUserId":"demo-patient-sunita-devi","title":"Brand versus generic levothyroxine","detail":"Your record shows levothyroxine 50 mcg, and the pharmacy dispensed Thyronorm 50 mcg. Please confirm both are the 50 mcg strength and take them the same way.","severity":"info","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb),
  ('demo-patient-joseph-thomas-indication-1', 'demo-doctor-vikram-shetty', 'demo-patient-joseph-thomas', 'Clopidogrel was not dispensed — confirm the copy and start it', 'This record shows dual antiplatelet therapy after a 2019 myocardial infarction and clopidogrel 75 mg was missing from the dispensed list. Please obtain the prescription copy and start the medicine without delay.', 'high', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-joseph-thomas-indication-1","doctorUserId":"demo-doctor-vikram-shetty","patientUserId":"demo-patient-joseph-thomas","title":"Clopidogrel was not dispensed — confirm the copy and start it","detail":"This record shows dual antiplatelet therapy after a 2019 myocardial infarction and clopidogrel 75 mg was missing from the dispensed list. Please obtain the prescription copy and start the medicine without delay.","severity":"high","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-joseph-thomas-indication-2', 'demo-doctor-vikram-shetty', 'demo-patient-joseph-thomas', 'Self-purchased ibuprofen with kidney disease', 'Ibuprofen 400 mg was added without a prescription. With chronic kidney disease stage 2 and antiplatelet therapy this needs a prescriber or pharmacist review before it continues.', 'review', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-joseph-thomas-indication-2","doctorUserId":"demo-doctor-vikram-shetty","patientUserId":"demo-patient-joseph-thomas","title":"Self-purchased ibuprofen with kidney disease","detail":"Ibuprofen 400 mg was added without a prescription. With chronic kidney disease stage 2 and antiplatelet therapy this needs a prescriber or pharmacist review before it continues.","severity":"review","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb),
  ('demo-patient-priya-menon-indication-1', 'demo-doctor-ananya-rao', 'demo-patient-priya-menon', 'Iron tablet causes nausea — take it after dinner', 'If the iron tablet upsets your stomach, take it after the evening meal instead of with breakfast. Do not stop the iron without advice.', 'info', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-priya-menon-indication-1","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-priya-menon","title":"Iron tablet causes nausea — take it after dinner","detail":"If the iron tablet upsets your stomach, take it after the evening meal instead of with breakfast. Do not stop the iron without advice.","severity":"info","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-priya-menon-indication-2', 'demo-doctor-ananya-rao', 'demo-patient-priya-menon', 'Check blood pressure and weight at every antenatal visit', 'Record your weight and blood pressure before each visit and bring the readings to the next review.', 'review', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-priya-menon-indication-2","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-priya-menon","title":"Check blood pressure and weight at every antenatal visit","detail":"Record your weight and blood pressure before each visit and bring the readings to the next review.","severity":"review","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb),
  ('demo-patient-lakshmi-devi-indication-1', 'demo-doctor-ananya-rao', 'demo-patient-lakshmi-devi', 'Recorded penicillin allergy and a penicillin-class antibiotic', 'Your record lists a penicillin allergy with anaphylaxis, and amoxicillin 500 mg was dispensed for a chest infection. Amoxicillin is a penicillin-class antibiotic. Please speak to the prescriber or pharmacist before the next dose.', 'high', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-lakshmi-devi-indication-1","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-lakshmi-devi","title":"Recorded penicillin allergy and a penicillin-class antibiotic","detail":"Your record lists a penicillin allergy with anaphylaxis, and amoxicillin 500 mg was dispensed for a chest infection. Amoxicillin is a penicillin-class antibiotic. Please speak to the prescriber or pharmacist before the next dose.","severity":"high","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-lakshmi-devi-indication-2', 'demo-doctor-ananya-rao', 'demo-patient-lakshmi-devi', 'Bring both inhalers to the next review', 'Bring the tiotropium and salbutamol inhalers and the spacer so inhaler technique can be checked at the next visit.', 'review', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-lakshmi-devi-indication-2","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-lakshmi-devi","title":"Bring both inhalers to the next review","detail":"Bring the tiotropium and salbutamol inhalers and the spacer so inhaler technique can be checked at the next visit.","severity":"review","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb),
  ('demo-patient-fatima-khan-indication-1', 'demo-doctor-meera-iyer', 'demo-patient-fatima-khan', 'Methotrexate is once weekly, not daily', 'The dispensed pack label reads “once daily”. Methotrexate 10 mg is taken once a week on the same day, and folic acid the day after. Please confirm the schedule with the pharmacist before the next dose.', 'review', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-fatima-khan-indication-1","doctorUserId":"demo-doctor-meera-iyer","patientUserId":"demo-patient-fatima-khan","title":"Methotrexate is once weekly, not daily","detail":"The dispensed pack label reads “once daily”. Methotrexate 10 mg is taken once a week on the same day, and folic acid the day after. Please confirm the schedule with the pharmacist before the next dose.","severity":"review","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-fatima-khan-indication-2', 'demo-doctor-meera-iyer', 'demo-patient-fatima-khan', 'Naproxen alongside methotrexate needs a review', 'Naproxen 500 mg was added without a prescription. Taken alongside methotrexate it needs a stomach-protection and monitoring review at the next appointment.', 'review', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-fatima-khan-indication-2","doctorUserId":"demo-doctor-meera-iyer","patientUserId":"demo-patient-fatima-khan","title":"Naproxen alongside methotrexate needs a review","detail":"Naproxen 500 mg was added without a prescription. Taken alongside methotrexate it needs a stomach-protection and monitoring review at the next appointment.","severity":"review","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb),
  ('demo-patient-ravi-shankar-indication-1', 'demo-doctor-ananya-rao', 'demo-patient-ravi-shankar', 'Two acid medicines on the list', 'Omeprazole and pantoprazole are both recorded. Continue omeprazole and stop pantoprazole once the current strip is finished, unless the prescriber says otherwise.', 'review', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-ravi-shankar-indication-1","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-ravi-shankar","title":"Two acid medicines on the list","detail":"Omeprazole and pantoprazole are both recorded. Continue omeprazole and stop pantoprazole once the current strip is finished, unless the prescriber says otherwise.","severity":"review","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-anjali-sharma-indication-1', 'demo-doctor-ananya-rao', 'demo-patient-anjali-sharma', 'Ibuprofen is both prescribed and recorded as an allergy', 'Your record lists ibuprofen 400 mg as a prescribed pain relief and also as an allergy that causes stomach irritation. Please confirm which is correct before the next dose.', 'high', '2026-10-14T09:00:00.000Z', '2026-10-14T09:00:00.000Z', '{"id":"demo-patient-anjali-sharma-indication-1","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-anjali-sharma","title":"Ibuprofen is both prescribed and recorded as an allergy","detail":"Your record lists ibuprofen 400 mg as a prescribed pain relief and also as an allergy that causes stomach irritation. Please confirm which is correct before the next dose.","severity":"high","createdAt":"2026-10-14T09:00:00.000Z","updatedAt":"2026-10-14T09:00:00.000Z"}'::jsonb),
  ('demo-patient-anjali-sharma-indication-2', 'demo-doctor-ananya-rao', 'demo-patient-anjali-sharma', 'Review the sleep aid with sertraline', 'Melatonin 3 mg is not part of this plan. Bring it to the next review so it can be reviewed alongside sertraline.', 'info', '2026-10-15T09:00:00.000Z', '2026-10-15T09:00:00.000Z', '{"id":"demo-patient-anjali-sharma-indication-2","doctorUserId":"demo-doctor-ananya-rao","patientUserId":"demo-patient-anjali-sharma","title":"Review the sleep aid with sertraline","detail":"Melatonin 3 mg is not part of this plan. Bring it to the next review so it can be reviewed alongside sertraline.","severity":"info","createdAt":"2026-10-15T09:00:00.000Z","updatedAt":"2026-10-15T09:00:00.000Z"}'::jsonb)
