-- MediHuman demo data. Generated by scripts/seed-demo-data.js --sql.
-- Fictional accounts on example.com addresses. Demo password: MediHuman@2026
set search_path = public, extensions;

on conflict (id) do update set email = excluded.email, role = excluded.role, patient_id = excluded.patient_id, password_hash = excluded.password_hash, supabase_user_id = excluded.supabase_user_id, google_sub = excluded.google_sub, doctor_profile = excluded.doctor_profile, email_confirmed_at = excluded.email_confirmed_at, created_at = excluded.created_at, updated_at = excluded.updated_at, data = excluded.data;

on conflict (user_id) do update set full_name = excluded.full_name, date_of_birth = excluded.date_of_birth, allergies = excluded.allergies, conditions = excluded.conditions, consent = excluded.consent, updated_at = excluded.updated_at, data = excluded.data;

on conflict (user_id) do update set items = excluded.items, updated_at = excluded.updated_at, data = excluded.data;

on conflict (id) do update set user_id = excluded.user_id, medication_name = excluded.medication_name, strength = excluded.strength, dose = excluded.dose, route = excluded.route, frequency = excluded.frequency, start_date = excluded.start_date, end_date = excluded.end_date, instructions = excluded.instructions, prescriber = excluded.prescriber, created_at = excluded.created_at, updated_at = excluded.updated_at, data = excluded.data;

on conflict (id) do update set user_id = excluded.user_id, prescription_medicines = excluded.prescription_medicines, dispensed_medicines = excluded.dispensed_medicines, matched = excluded.matched, missing = excluded.missing, unexpected = excluded.unexpected, is_exact_match = excluded.is_exact_match, notes = excluded.notes, created_at = excluded.created_at, updated_at = excluded.updated_at, data = excluded.data;

on conflict (id) do update set doctor_user_id = excluded.doctor_user_id, patient_user_id = excluded.patient_user_id, status = excluded.status, requested_at = excluded.requested_at, responded_at = excluded.responded_at, revoked_at = excluded.revoked_at, data = excluded.data;

on conflict (id) do update set doctor_user_id = excluded.doctor_user_id, patient_user_id = excluded.patient_user_id, title = excluded.title, detail = excluded.detail, severity = excluded.severity, created_at = excluded.created_at, updated_at = excluded.updated_at, data = excluded.data;

on conflict (id) do update set recipient_user_id = excluded.recipient_user_id, actor_user_id = excluded.actor_user_id, type = excluded.type, title = excluded.title, message = excluded.message, entity_type = excluded.entity_type, entity_id = excluded.entity_id, read_at = excluded.read_at, created_at = excluded.created_at, data = excluded.data;

on conflict (id) do update set actor_user_id = excluded.actor_user_id, action = excluded.action, entity_type = excluded.entity_type, entity_id = excluded.entity_id, outcome = excluded.outcome, created_at = excluded.created_at, data = excluded.data;

-- Supabase Auth accounts for the demo logins.
create extension if not exists pgcrypto;
create or replace function public.medihuman_demo_hash(password text) returns text
language plpgsql as $$
declare
  crypto_schema text;
begin
  select n.nspname into crypto_schema from pg_proc p join pg_namespace n on n.oid = p.pronamespace where p.proname = 'crypt' and p.pronargs = 2 limit 1;
  if crypto_schema is null then raise exception 'pgcrypto is required to seed the demo accounts'; end if;
  return execute format('select %I.crypt($1, %I.gen_salt(''bf''))', crypto_schema, crypto_schema);
end;
$$;

do $$
declare
  demo record;
  demo_id uuid;
begin
  for demo in select * from jsonb_to_recordset('[{"email":"ananya.rao@clinic.example.com","role":"doctor"},{"email":"vikram.shetty@clinic.example.com","role":"doctor"},{"email":"meera.iyer@clinic.example.com","role":"doctor"},{"email":"rohan.gupta@clinic.example.com","role":"doctor"},{"email":"ramesh.kumar@example.com","role":"patient"},{"email":"sunita.devi@example.com","role":"patient"},{"email":"joseph.thomas@example.com","role":"patient"},{"email":"priya.menon@example.com","role":"patient"},{"email":"lakshmi.devi@example.com","role":"patient"},{"email":"fatima.khan@example.com","role":"patient"},{"email":"ravi.shankar@example.com","role":"patient"},{"email":"anjali.sharma@example.com","role":"patient"}]'::jsonb) as demo(email text, role text) loop
    select id into demo_id from auth.users where email = demo.email;
    if demo_id is null then
      demo_id := gen_random_uuid();
      values (demo_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', demo.email, public.medihuman_demo_hash('MediHuman@2026'), now(), jsonb_build_object('provider', 'email', 'providers', array['email']), jsonb_build_object('medihuman_role', demo.role, 'medihuman_demo', true), now(), now());
      values (gen_random_uuid(), demo_id, demo_id, jsonb_build_object('sub', demo_id::text, 'email', demo.email, 'email_verified', true), 'email', now(), now(), now());
    else
      update auth.users set encrypted_password = public.medihuman_demo_hash('MediHuman@2026'), email_confirmed_at = now(), raw_user_meta_data = jsonb_build_object('medihuman_role', demo.role, 'medihuman_demo', true) where id = demo_id;
    end if;
  end loop;
end $$;
